package cn.kejian.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.webkit.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;
public final class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> chooser;private static final int FILE=101,NOTIFY=102,COURSE_NOTIFY=103;private boolean askInFlight=false;
 private static final String BASE="https://appassets.androidplatform.net/assets/";
 @Override public void onCreate(Bundle b){super.onCreate(b);AlarmScheduler.channel(this);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(250,249,245));web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);
 root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()),ime=insets.getInsets(WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return Build.VERSION.SDK_INT>=30?WindowInsets.CONSUMED:insets.consumeSystemWindowInsets();});
 if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);else getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(Build.VERSION.SDK_INT>=29)getWindow().setNavigationBarContrastEnforced(false);root.requestApplyInsets();
 WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);web.setBackgroundColor(Color.rgb(250,249,245));WebView.setWebContentsDebuggingEnabled(false);
 web.addJavascriptInterface(new Bridge(),"KejianNative");
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !isLocal(r.getUrl());}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!isLocal(u))return blocked();String path=u.getPath().substring("/assets/".length());if(path.contains("..")||path.contains("\\")||path.startsWith("/"))return blocked();try{String mime=path.endsWith(".html")?"text/html":path.endsWith(".js")?"application/javascript":path.endsWith(".css")?"text/css":path.endsWith(".png")?"image/png":"application/octet-stream";return new WebResourceResponse(mime,"UTF-8",getAssets().open(path));}catch(IOException e){return blocked();}}@Override public void onPageFinished(WebView v,String url){v.evaluateJavascript("window.dispatchEvent(new Event('native-status'));",null);}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);String[] types=params.getAcceptTypes();ArrayList<String> mime=new ArrayList<>();for(String group:types){for(String t:group.split(",")){t=t.trim();if(t.contains("/"))mime.add(t);}}if(!mime.isEmpty())i.putExtra(Intent.EXTRA_MIME_TYPES,mime.toArray(new String[0]));try{startActivityForResult(i,FILE);}catch(ActivityNotFoundException e){chooser.onReceiveValue(null);chooser=null;Toast.makeText(MainActivity.this,"没有可用的文件选择器",Toast.LENGTH_LONG).show();}return true;}});
 web.loadUrl(BASE+"index.html");
 }
 private boolean isLocal(Uri u){return "https".equals(u.getScheme())&&"appassets.androidplatform.net".equals(u.getHost())&&u.getPath()!=null&&u.getPath().startsWith("/assets/");}
 private WebResourceResponse blocked(){return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
 public final class Bridge {
  private boolean validKey(String k){return AlarmScheduler.STATE.equals(k)||"kejian-pet-v1".equals(k);}
  @JavascriptInterface public String getItem(String key){return validKey(key)?AlarmScheduler.prefs(MainActivity.this).getString(key,null):null;}
  @JavascriptInterface public boolean setItem(String key,String value){if(!validKey(key)||value==null||value.length()>8*1024*1024)return false;try{JSONObject data=new JSONObject(value);if(AlarmScheduler.STATE.equals(key)){if(data.getJSONArray("courses").length()>2000||data.getJSONArray("reminders").length()>1000)return false;JSONArray reminders=data.getJSONArray("reminders");for(int n=0;n<reminders.length();n++){JSONObject r=reminders.getJSONObject(n);if(r.optString("id").isEmpty()||r.optString("id").length()>256||r.optString("name").length()>120)return false;java.time.LocalDate.parse(r.optString("date"));java.time.LocalTime.parse(r.optString("time"));}}boolean saved=AlarmScheduler.prefs(MainActivity.this).edit().putString(key,value).commit();if(saved&&AlarmScheduler.STATE.equals(key))AlarmScheduler.reconcile(MainActivity.this);return saved;}catch(Exception e){return false;}}
  @JavascriptInterface public boolean removeItem(String key){if(!validKey(key))return false;boolean ok=AlarmScheduler.prefs(MainActivity.this).edit().remove(key).commit();if(AlarmScheduler.STATE.equals(key))AlarmScheduler.reconcile(MainActivity.this);return ok;}
  @JavascriptInterface public String validateReminder(String date,String time){try{long when=AlarmPlan.timestamp(date,time,java.time.ZoneId.systemDefault());return when>System.currentTimeMillis()?"":"请选择未来的提醒时间";}catch(Exception e){return e.getMessage();}}
  @JavascriptInterface public String inflateRaw(String encoded,int limit){return RawInflater.decode(encoded,limit);}

  @JavascriptInterface public String notificationStatus(){return AlarmScheduler.statusJson(MainActivity.this);}
  @JavascriptInterface public void courseNotificationSettings(){runOnUiThread(()->courseSettings());}
  @JavascriptInterface public void enableReminders(){runOnUiThread(()->askPermissions());}
 }
 private void notificationSettings(){try{startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}catch(ActivityNotFoundException e){Toast.makeText(this,"请在系统设置中找到课间的通知设置",Toast.LENGTH_LONG).show();}}
 private void courseSettings(){if(askInFlight)return;askInFlight=true;boolean[] selected={AlarmScheduler.prefs(this).getBoolean(CourseNotification.ON,false),AlarmScheduler.prefs(this).getBoolean(CourseNotification.DETAILS,false)};
 LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);int pad=(int)(24*getResources().getDisplayMetrics().density);box.setPadding(pad,pad/2,pad,pad/2);TextView explanation=new TextView(this);explanation.setText("静音显示本节课、下节课与时间地点。系统需允许通知及锁屏展示；隐藏敏感内容时可能只显示提示或完全不显示。省电可延后切课，系统也可能移除卡片，不保证常驻。关闭将取消卡片及后续更新。");box.addView(explanation);String[] labels={"启用课程通知卡片","允许锁屏显示课程详情（含地点）"};for(int i=0;i<2;i++){final int index=i;CheckBox check=new CheckBox(this);check.setText(labels[i]);check.setChecked(selected[i]);check.setOnCheckedChangeListener((v,checked)->selected[index]=checked);box.addView(check);}ScrollView scroll=new ScrollView(this);scroll.addView(box);
 new AlertDialog.Builder(this).setTitle("锁屏课程卡片").setView(scroll)
 .setPositiveButton("保存",(d,w)->{askInFlight=false;if(!CourseNotification.configure(this,selected[0],selected[1])){Toast.makeText(this,"设置保存失败，请重试",Toast.LENGTH_LONG).show();return;}if(selected[0])coursePermission();})
 .setNeutralButton("系统通知设置",(d,w)->{askInFlight=false;notificationSettings();}).setNegativeButton("取消",(d,w)->askInFlight=false).setOnCancelListener(d->askInFlight=false).show();
 }
 private void coursePermission(){if(askInFlight)return;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){
 if(AlarmScheduler.prefs(this).getBoolean("course_permission_asked",false)){courseBlocked();return;}askInFlight=true;AlarmScheduler.prefs(this).edit().putBoolean("course_permission_asked",true).commit();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},COURSE_NOTIFY);return;}
 CourseNotification.reconcile(this);if(!CourseNotification.enabled(this))courseBlocked();
 }
 private void courseBlocked(){new AlertDialog.Builder(this).setTitle("课程卡片暂不能显示").setMessage("课程卡片开关已保存，但系统通知权限或“锁屏课程卡片”渠道未允许。可打开通知设置，并检查系统的锁屏通知和敏感内容选项；课表仍保留。") .setPositiveButton("打开通知设置",(d,w)->notificationSettings()).setNegativeButton("稍后",null).show();}
 private void askPermissions(){if(askInFlight)return;askInFlight=true;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setTitle("启用提醒通知").setMessage("提醒已保存在本机。允许通知后，课间才能在你指定的时间提醒你。拒绝后仍保留记录。").setPositiveButton("允许通知",(d,w)->requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},NOTIFY)).setNegativeButton("暂时不启用",(d,w)->{askInFlight=false;statusChanged();}).setOnCancelListener(d->{askInFlight=false;statusChanged();}).show();return;}askInFlight=false;if(!AlarmScheduler.enabled(this)){new AlertDialog.Builder(this).setTitle("通知尚未启用").setMessage("记录已保存。系统或提醒渠道当前关闭，可以在设置中启用。").setPositiveButton("打开通知设置",(d,w)->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()))).setNegativeButton("稍后",null).show();return;}if(Build.VERSION.SDK_INT>=31&&!AlarmScheduler.exact(this)){new AlertDialog.Builder(this).setTitle("按指定时间提醒").setMessage("当前已安排可延后的提醒。允许“闹钟和提醒”后，才会使用精确闹钟；省电或强行停止应用仍可能影响通知。").setPositiveButton("打开闹钟设置",(d,w)->{try{startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException e){Toast.makeText(this,"此设备不提供该设置，提醒可能延后",Toast.LENGTH_LONG).show();}}).setNegativeButton("允许延后",null).show();}AlarmScheduler.reconcile(this);statusChanged();}
 private void statusChanged(){if(web!=null)web.evaluateJavascript("window.dispatchEvent(new Event('native-status'));",null);}
 @Override public void onRequestPermissionsResult(int code,String[] p,int[] grants){super.onRequestPermissionsResult(code,p,grants);askInFlight=false;AlarmScheduler.reconcile(this);statusChanged();if(code==COURSE_NOTIFY){CourseNotification.reconcile(this);if(grants.length==0||grants[0]!=PackageManager.PERMISSION_GRANTED)courseBlocked();return;}if(code==NOTIFY&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)askPermissions();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==FILE&&chooser!=null){Uri[] values=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();if("content".equals(uri.getScheme()))values=new Uri[]{uri};}chooser.onReceiveValue(values);chooser=null;}}
 @Override protected void onResume(){super.onResume();AlarmScheduler.reconcile(this);statusChanged();if(web!=null){web.onResume();web.evaluateJavascript("window.dispatchEvent(new Event('focus'));",null);}}
 @Override protected void onPause(){if(web!=null)web.onPause();super.onPause();}
 @Override public void onBackPressed(){web.evaluateJavascript("window.AndroidAppBack ? window.AndroidAppBack() : false",result->{if(!"true".equals(result))MainActivity.super.onBackPressed();});}
 @Override protected void onDestroy(){if(chooser!=null){chooser.onReceiveValue(null);chooser=null;}if(web!=null){web.removeJavascriptInterface("KejianNative");web.destroy();}super.onDestroy();}
}
